import{_ as l,a0 as t,w as o,s as d,ao as c,I as p,x as e,a1 as n,A as i}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const x=JSON.parse('{"title":"用 Linux 命令行解决 Wordle 问题 | LCTT x X-CMD","titleTemplate":false,"description":"用 Linux 命令行解决 Wordle 问题 | LCTT (202202) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"用 Linux 命令行解决 Wordle 问题 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"用 Linux 命令行解决 Wordle 问题 | LCTT (202202) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202202/20220116 Solve Wordle using the Linux command line","title":"用 Linux 命令行解决 Wordle 问题","tag":"202202","desc":""},"relativePath":"202202/20220116 Solve Wordle using the Linux command line.md","filePath":"[post].md"}'),r={name:"202202/20220116 Solve Wordle using the Linux command line.md"};function g(u,s,h,k,b,m){const a=t("Link");return o(),d("div",null,[s[15]||(s[15]=c(`<h1 id="用-linux-命令行解决-wordle-问题" tabindex="-1">用 Linux 命令行解决 Wordle 问题 <a class="header-anchor" href="#用-linux-命令行解决-wordle-问题" aria-label="Permalink to “用 Linux 命令行解决 Wordle 问题”">​</a></h1><blockquote><p>使用 Linux 的 grep 和 fgrep 命令来赢得你最喜欢的基于单词的猜测游戏。</p></blockquote><p><img src="https://opensource.com/sites/default/files/styles/image-full-size/public/lead-images/linux_keyboard_desktop.png?itok=I2nGw78_" alt="Linux keys on the keyboard for a desktop computer" title="Linux keys on the keyboard for a desktop computer"></p><p>我最近有点迷恋上了一个在线单词猜谜游戏，在这个游戏中，你有六次机会来猜一个随机的五个字母的单词。这个词每天都在变化，而且你每天只能玩一次。每次猜测后，你猜测中的每个字母都会被高亮显示：灰色表示该字母没有出现在神秘单词中，黄色表示该字母出现在单词中，但不在那个位置，绿色表示该字母出现在单词中的那个正确位置。</p><p>下面是你如何使用 Linux 命令行来帮助你玩像 Wordle 这样的猜测游戏。我用这个方法来帮助我解决 1 月 6 日的谜题：</p><h3 id="第一次尝试" tabindex="-1">第一次尝试 <a class="header-anchor" href="#第一次尝试" aria-label="Permalink to “第一次尝试”">​</a></h3><p>Linux 系统在 <code>/usr/share/dict/words</code> 文件中保存了一个单词词典。这是一个很长的纯文本文件。我的系统的单词文件里有超过 479,800 个条目。该文件既包含纯文本，也包含专有名词（名字、地点等等）。</p><p>为了开始我的第一次猜测，我只想得到一个长度正好是五个字母的纯文本词的列表。要做到这一点，我使用这个 <code>grep</code> 命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ grep &#39;^[a-z][a-z][a-z][a-z][a-z]$&#39; /usr/share/dict/words &gt; myguess</span></span></code></pre></div><p><code>grep</code> 命令使用正则表达式来进行搜索。你可以用正则表达式做很多事情，但为了帮助我解决 Wordle 问题，我只需要基本的东西。<code>^</code> 表示一行的开始，<code>$</code> 表示一行的结束。在两者之间，我指定了五个 <code>[a-z]</code> 的实例，表示从 a 到 z 的任何小写字母。</p><p>我还可以使用 <code>wc</code> 命令来查看我的可能单词列表，“只有” 15,000 个单词：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ wc -l myguess</span></span>
<span class="line"><span>15034 myguess</span></span></code></pre></div><p>从这个列表中，我随机挑选了一个五个字母的单词：<code>acres</code>。<code>a</code> 被设置为黄色，意味着该字母存在于神秘单词的某处，但不在第一位置。其他字母是灰色的，所以我知道它们并不存在于今天的单词中。</p><p><img src="https://opensource.com/sites/default/files/acres.png" alt="acres word attempt" title="acres word attempt"></p><h3 id="第二次尝试" tabindex="-1">第二次尝试 <a class="header-anchor" href="#第二次尝试" aria-label="Permalink to “第二次尝试”">​</a></h3><p>对于我的下一个猜测，我想得到一个包含 <code>a</code> 的所有单词的列表，但不是在第一位置。我的列表也不应该包括字母 <code>c</code>、<code>r</code>、<code>e</code> 或 <code>s</code>。让我们把这个问题分解成几个步骤。</p><p>为了得到所有带 a 的单词的列表，我使用 <code>fgrep</code>（固定字符串 grep）命令。<code>fgrep</code> 命令也像 <code>grep</code> 一样搜索文本，但不使用正则表达式：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ fgrep a myguess &gt; myguess2</span></span></code></pre></div><p>这使我的下一个猜测的可能列表从 15,000 个字下降到 6,600 个字：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ wc -l myguess myguess2</span></span>
<span class="line"><span> 15034 myguess</span></span>
<span class="line"><span>  6634 myguess2</span></span>
<span class="line"><span> 21668 total</span></span></code></pre></div><p>但是这个单词列表中的第一个位置也有字母 <code>a</code>，这是我不想要的。游戏已经表明字母 <code>a</code> 存在于其他位置。我可以用 <code>grep</code> 修改我的命令，以寻找在第一个位置包含其他字母的词。这就把我可能的猜测缩小到了 5500 个单词：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ fgrep a myguess | grep &#39;^[b-z]&#39; &gt; myguess2</span></span>
<span class="line"><span>$ wc -l myguess myguess2</span></span>
<span class="line"><span> 15034 myguess</span></span>
<span class="line"><span>  5566 myguess2</span></span>
<span class="line"><span> 20600 total</span></span></code></pre></div><p>但我知道这个神秘的词也不包括字母 <code>c</code>、<code>r</code>、<code>e</code> 或 <code>s</code>。我可以使用另一个 <code>grep</code> 命令，在搜索中省略这些字母：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ fgrep a myguess | grep &#39;^[b-z]&#39; | grep -v &#39;[cres]&#39; &gt; myguess2</span></span>
<span class="line"><span>$ wc -l myguess myguess2</span></span>
<span class="line"><span>15034 myguess</span></span>
<span class="line"><span> 1257 myguess2</span></span>
<span class="line"><span>16291 total</span></span></code></pre></div><p><code>-v</code> 选项意味着反转搜索，所以 <code>grep</code> 将只返回不符合正则表达式 <code>[cres]</code> 或单列字母 <code>c</code>、<code>r</code>、<code>e</code> 或 <code>s</code> 的行。有了这个额外的 <code>grep</code> 命令，我把下一个猜测的范围大大缩小到只有 1200 个可能的单词，这些单词在某处有一个 <code>a</code>，但不在第一位置，并且不包含 <code>c</code>、<code>r</code>、<code>e</code>、或 <code>s</code>。</p><p>在查看了这个列表后，我决定尝试一下 <code>balmy</code> 这个词。</p><p><img src="https://opensource.com/sites/default/files/balmy.png" alt="balmy word attempt" title="balmy word attempt"></p><h3 id="第三次尝试" tabindex="-1">第三次尝试 <a class="header-anchor" href="#第三次尝试" aria-label="Permalink to “第三次尝试”">​</a></h3><p>这一次，字母 <code>b</code> 和 <code>a</code> 被高亮显示为绿色，意味着我把这些字母放在了正确的位置。字母 <code>l</code> 是黄色的，所以这个字母存在于单词的其他地方，但不是在那个位置。字母 <code>m</code> 和 <code>y</code> 是灰色的，所以我可以从我的下一个猜测中排除这些。</p><p>为了确定下一个可能的单词列表，我可以使用另一组 <code>grep</code> 命令。我知道这个词以 <code>ba</code> 开头，所以我可以从这里开始搜索：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ grep &#39;^ba&#39; myguess2 &gt; myguess3</span></span>
<span class="line"><span>$ wc -l myguess3</span></span>
<span class="line"><span>77 myguess3</span></span></code></pre></div><p>这只有 77 个词! 我可以进一步缩小范围，寻找除第三位外还包含字母 <code>l</code> 的词：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ grep &#39;^ba[^l]&#39; myguess2 &gt; myguess3</span></span>
<span class="line"><span>$ wc -l myguess3</span></span>
<span class="line"><span>61 myguess3</span></span></code></pre></div><p>方括号 <code>[^l]</code> 内的 <code>^</code> 表示不是这个字母列表，即不是字母 <code>l</code>。这使我的可能单词列表达到 61 个，并非所有的单词都包含字母 <code>l</code>，我可以用另一个 <code>grep</code> 搜索来消除这些单词：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ grep &#39;^ba[^l]&#39; myguess2 | fgrep l &gt; myguess3</span></span>
<span class="line"><span>$ wc -l myguess3</span></span>
<span class="line"><span>10 myguess3</span></span></code></pre></div><p>这些词中有些可能包含字母 <code>m</code> 和 <code>y</code>，而这些字母并不在今天的神秘词中。我可以再进行一次反转 <code>grep</code> 搜索，将它们从我的猜测列表中删除：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ grep &#39;^ba[^l]&#39; myguess2 | fgrep l | grep -v &#39;[my]&#39; &gt; myguess3</span></span>
<span class="line"><span>$ wc -l myguess3</span></span>
<span class="line"><span>7 myguess3</span></span></code></pre></div><p>我的可能的单词列表现在非常短，只有七个单词!</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ cat myguess3</span></span>
<span class="line"><span>babul</span></span>
<span class="line"><span>bailo</span></span>
<span class="line"><span>bakal</span></span>
<span class="line"><span>bakli</span></span>
<span class="line"><span>banal</span></span>
<span class="line"><span>bauld</span></span>
<span class="line"><span>baulk</span></span></code></pre></div><p>我选择 <code>banal</code> 作为我下一次猜测的可能的词，而这恰好是正确的。</p><p><img src="https://opensource.com/sites/default/files/banal.png" alt="banal word attempt" title="banal word attempt"></p><h3 id="正则表达式的力量" tabindex="-1">正则表达式的力量 <a class="header-anchor" href="#正则表达式的力量" aria-label="Permalink to “正则表达式的力量”">​</a></h3><p>Linux 的命令行提供了强大的工具来帮助你完成实际工作。<code>grep</code> 和 <code>fgrep</code> 命令在扫描单词列表方面提供了极大的灵活性。对于一个基于单词的猜测游戏，<code>grep</code> 帮助识别了一个包含 15000 个可能的单词的列表。在猜测并知道哪些字母出现在神秘的单词中，哪些没有，<code>grep</code> 和 <code>fgrep</code> 帮助将选项缩小到 1200 个单词，然后只剩下 7 个单词。这就是命令行的力量。</p><hr>`,44)),p("p",null,[s[1]||(s[1]=e("via: ",-1)),n(a,{href:"https://opensource.com/article/22/1/word-game-linux-command-line"},{default:i(()=>[...s[0]||(s[0]=[e("https://opensource.com/article/22/1/word-game-linux-command-line",-1)])]),_:1})]),p("p",null,[s[6]||(s[6]=e("作者：",-1)),n(a,{href:"https://opensource.com/users/jim-hall"},{default:i(()=>[...s[2]||(s[2]=[e("Jim Hall",-1)])]),_:1}),s[7]||(s[7]=e(" 选题：",-1)),n(a,{href:"https://github.com/lujun9972"},{default:i(()=>[...s[3]||(s[3]=[e("lujun9972",-1)])]),_:1}),s[8]||(s[8]=e(" 译者：",-1)),n(a,{href:"https://github.com/geekpi"},{default:i(()=>[...s[4]||(s[4]=[e("geekpi",-1)])]),_:1}),s[9]||(s[9]=e(" 校对：",-1)),n(a,{href:"https://github.com/wxy"},{default:i(()=>[...s[5]||(s[5]=[e("wxy",-1)])]),_:1})]),p("p",null,[s[12]||(s[12]=e("本文由 ",-1)),n(a,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...s[10]||(s[10]=[e("LCTT",-1)])]),_:1}),s[13]||(s[13]=e(" 原创编译，",-1)),n(a,{href:"https://linux.cn/"},{default:i(()=>[...s[11]||(s[11]=[e("Linux中国",-1)])]),_:1}),s[14]||(s[14]=e(" 荣誉推出",-1))])])}const C=l(r,[["render",g]]);export{x as __pageData,C as default};
